Here is the commit message:
ipv6: fix cleanup ordering for ip6_mr failure

Commit 15e668070a64 ("ipv6: reorder icmpv6_init() and ip6_mr_init()")
moved the cleanup label for ipmr_fail, but should have changed the
contents of the cleanup labels as well. Now we can end up cleaning up
icmpv6 even though it hasn't been initialized (jump to icmp_fail or
ipmr_fail).

Simply undo things in the reverse order of their initialization.

Example of panic (triggered by faking a failure of icmpv6_init):

    kasan: GPF could be caused by NULL-ptr deref or user memory access
    general protection fault: 0000 [#1] PREEMPT SMP KASAN PTI
    [...]
    RIP: 0010:__list_del_entry_valid+0x79/0x160
    [...]
    Call Trace:
     ? lock_release+0x8a0/0x8a0
     unregister_pernet_operations+0xd4/0x560
     ? ops_free_list+0x480/0x480
     ? down_write+0x91/0x130
     ? unregister_pernet_subsys+0x15/0x30
     ? down_read+0x1b0/0x1b0
     ? up_read+0x110/0x110
     ? kmem_cache_create_usercopy+0x1b4/0x240
     unregister_pernet_subsys+0x1d/0x30
     icmpv6_cleanup+0x1d/0x30
     inet6_init+0x1b5/0x23f

Fixes: 15e668070a64 ("ipv6: reorder icmpv6_init() and ip6_mr_init()")
Signed-off-by: Sabrina Dubroca <sd@queasysnail.net>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by an incorrect cleanup order in the `inet6_init()` function, where the cleanup for `icmpv6` was attempted before it was initialized, leading to potential null pointer dereferences and general protection faults. This issue arose from a previous commit that reordered the initialization functions without appropriately adjusting the corresponding cleanup sequence.

Here is the patch:

 static int __init inet6_init(void)
 {
 	struct list_head *r;
 	int err = 0;

 	sock_skb_cb_check_size(sizeof(struct inet6_skb_parm));

 	/* Register the socket-side information for inet6_create.  */
 	for (r = &inetsw6[0]; r < &inetsw6[SOCK_MAX]; ++r)
 		INIT_LIST_HEAD(r);

 	if (disable_ipv6_mod) {
 		pr_info("Loaded, but administratively disabled, reboot required to enable\n");
 		goto out;
 	}

 	err = proto_register(&tcpv6_prot, 1);
 	if (err)
 		goto out;

 	err = proto_register(&udpv6_prot, 1);
 	if (err)
 		goto out_unregister_tcp_proto;

 	err = proto_register(&udplitev6_prot, 1);
 	if (err)
 		goto out_unregister_udp_proto;

 	err = proto_register(&rawv6_prot, 1);
 	if (err)
 		goto out_unregister_udplite_proto;

 	err = proto_register(&pingv6_prot, 1);
 	if (err)
 		goto out_unregister_ping_proto;

 	/* We MUST register RAW sockets before we create the ICMP6,
 	 * IGMP6, or NDISC control sockets.
 	 */
 	err = rawv6_init();
 	if (err)
 		goto out_unregister_raw_proto;

 	/* Register the family here so that the init calls below will
 	 * be able to create sockets. (?? is this dangerous ??)
 	 */
 	err = sock_register(&inet6_family_ops);
 	if (err)
 		goto out_sock_register_fail;

 	/*
 	 *	ipngwg API draft makes clear that the correct semantics
 	 *	for TCP and UDP is to consider one TCP and UDP instance
 	 *	in a host available by both INET and INET6 APIs and
 	 *	able to communicate via both network protocols.
 	 */

 	err = register_pernet_subsys(&inet6_net_ops);
 	if (err)
 		goto register_pernet_fail;
 	err = ip6_mr_init();
 	if (err)
 		goto ipmr_fail;
 	err = icmpv6_init();
 	if (err)
 		goto icmp_fail;
 	err = ndisc_init();
 	if (err)
 		goto ndisc_fail;
 	err = igmp6_init();
 	if (err)
 		goto igmp_fail;

 	err = ipv6_netfilter_init();
 	if (err)
 		goto netfilter_fail;
 	/* Create /proc/foo6 entries. */
 #ifdef CONFIG_PROC_FS
 	err = -ENOMEM;
 	if (raw6_proc_init())
 		goto proc_raw6_fail;
 	if (udplite6_proc_init())
 		goto proc_udplite6_fail;
 	if (ipv6_misc_proc_init())
 		goto proc_misc6_fail;
 	if (if6_proc_init())
 		goto proc_if6_fail;
 #endif
 	err = ip6_route_init();
 	if (err)
 		goto ip6_route_fail;
 	err = ndisc_late_init();
 	if (err)
 		goto ndisc_late_fail;
 	err = ip6_flowlabel_init();
 	if (err)
 		goto ip6_flowlabel_fail;
 	err = addrconf_init();
 	if (err)
 		goto addrconf_fail;

 	/* Init v6 extension headers. */
 	err = ipv6_exthdrs_init();
 	if (err)
 		goto ipv6_exthdrs_fail;

 	err = ipv6_frag_init();
 	if (err)
 		goto ipv6_frag_fail;

 	/* Init v6 transport protocols. */
 	err = udpv6_init();
 	if (err)
 		goto udpv6_fail;

 	err = udplitev6_init();
 	if (err)
 		goto udplitev6_fail;

 	err = udpv6_offload_init();
 	if (err)
 		goto udpv6_offload_fail;

 	err = tcpv6_init();
 	if (err)
 		goto tcpv6_fail;

 	err = ipv6_packet_init();
 	if (err)
 		goto ipv6_packet_fail;

 	err = pingv6_init();
 	if (err)
 		goto pingv6_fail;

 	err = calipso_init();
 	if (err)
 		goto calipso_fail;

 	err = seg6_init();
 	if (err)
 		goto seg6_fail;

 	err = igmp6_late_init();
 	if (err)
 		goto igmp6_late_err;

 #ifdef CONFIG_SYSCTL
 	err = ipv6_sysctl_register();
 	if (err)
 		goto sysctl_fail;
 #endif

 	/* ensure that ipv6 stubs are visible only after ipv6 is ready */
 	wmb();
 	ipv6_stub = &ipv6_stub_impl;
 	ipv6_bpf_stub = &ipv6_bpf_stub_impl;
 out:
 	return err;

 #ifdef CONFIG_SYSCTL
 sysctl_fail:
 	igmp6_late_cleanup();
 #endif
 igmp6_late_err:
 	seg6_exit();
 seg6_fail:
 	calipso_exit();
 calipso_fail:
 	pingv6_exit();
 pingv6_fail:
 	ipv6_packet_cleanup();
 ipv6_packet_fail:
 	tcpv6_exit();
 tcpv6_fail:
 	udpv6_offload_exit();
 udpv6_offload_fail:
 	udplitev6_exit();
 udplitev6_fail:
 	udpv6_exit();
 udpv6_fail:
 	ipv6_frag_exit();
 ipv6_frag_fail:
 	ipv6_exthdrs_exit();
 ipv6_exthdrs_fail:
 	addrconf_cleanup();
 addrconf_fail:
 	ip6_flowlabel_cleanup();
 ip6_flowlabel_fail:
 	ndisc_late_cleanup();
 ndisc_late_fail:
 	ip6_route_cleanup();
 ip6_route_fail:
 #ifdef CONFIG_PROC_FS
 	if6_proc_exit();
 proc_if6_fail:
 	ipv6_misc_proc_exit();
 proc_misc6_fail:
 	udplite6_proc_exit();
 proc_udplite6_fail:
 	raw6_proc_exit();
 proc_raw6_fail:
 #endif
 	ipv6_netfilter_fini();
 netfilter_fail:
 	igmp6_cleanup();
 igmp_fail:
 	ndisc_cleanup();
 ndisc_fail:
-	ip6_mr_cleanup();
+	icmpv6_cleanup();
 icmp_fail:
-	unregister_pernet_subsys(&inet6_net_ops);
+	ip6_mr_cleanup();
 ipmr_fail:
-	icmpv6_cleanup();
+	unregister_pernet_subsys(&inet6_net_ops);
 register_pernet_fail:
 	sock_unregister(PF_INET6);
 	rtnl_unregister_all(PF_INET6);
 out_sock_register_fail:
 	rawv6_exit();
 out_unregister_ping_proto:
 	proto_unregister(&pingv6_prot);
 out_unregister_raw_proto:
 	proto_unregister(&rawv6_prot);
 out_unregister_udplite_proto:
 	proto_unregister(&udplitev6_prot);
 out_unregister_udp_proto:
 	proto_unregister(&udpv6_prot);
 out_unregister_tcp_proto:
 	proto_unregister(&tcpv6_prot);
 	goto out;
 }
 module_init(inet6_init);


